.tab {
  flex: 0 0 auto;
  white-space: nowrap;
  font-family: var(--font-ui);
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: var(--label-spacing);
  color: var(--mute);
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  padding: 5px 9px 7px;
  cursor: pointer;
  transition: color 0.14s ease, border-color 0.14s ease;
}

